From 843c92be86628f8f85a4b3dfc7deb75b2618f65f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:57:59 +0100
Subject: [PATCH] applet: show the lowest application volume on the
 Applications tab

When an application had been turned down, nothing on the Devices tab
hinted at it, so users kept raising the device volume instead. Now the
Applications tab shows the lowest playback volume when it's below 100%.

BUG: 516642
---
 applet/main.qml | 31 ++++++++++++++++++++++++++++++-
 1 file changed, 30 insertions(+), 1 deletion(-)

diff --git a/applet/main.qml b/applet/main.qml
index 1e44cded..f0f08234 100644
--- a/applet/main.qml
+++ b/applet/main.qml
@@ -365,9 +365,38 @@ PlasmoidItem {

                     PC3.TabButton {
                         id: streamsTab
-                        text: i18n("Applications")
+
+                        property int revision: 0
+                        // Lowest volume among playing applications, or -1 if none is below 100%
+                        readonly property int lowestPercent: {
+                            revision;
+                            let lowest = -1;
+                            for (let i = 0; i < streamVolumes.count; ++i) {
+                                const stream = streamVolumes.objectAt(i);
+                                if (stream && stream.percent < 100 && (lowest < 0 || stream.percent < lowest)) {
+                                    lowest = stream.percent;
+                                }
+                            }
+                            return lowest;
+                        }
+
+                        text: lowestPercent >= 0
+                            ? i18nc("@title:tab %1 is the lowest volume of an application playing audio", "Applications (%1%)", lowestPercent)
+                            : i18n("Applications")

                         KeyNavigation.up: fullRep.KeyNavigation.up
+
+                        Instantiator {
+                            id: streamVolumes
+                            model: paSinkInputFilterModel
+                            delegate: QtObject {
+                                required property var model
+                                readonly property int percent: model.HasVolume === false ? 100
+                                    : model.Muted ? 0 : main.volumePercent(model.Volume)
+                            }
+                            onObjectAdded: streamsTab.revision++
+                            onObjectRemoved: streamsTab.revision++
+                        }
                     }
                 }

